1	package chainledger
2	
3	import (
4		"encoding/json"
5		"reflect"
6		"strings"
7		"testing"
8	)
9	
10	// compareDoc builds a lineage document from names and directed dependencies,
11	// so tests can freely reorder or repeat nodes and edges without hand-writing
12	// JSON.
13	func compareDoc(t *testing.T, nodes []string, edges [][2]string) string {
14		t.Helper()
15		type edge struct {
16			From string `json:"from"`
17			To   string `json:"to"`
18		}
19		doc := struct {
20			Nodes []string `json:"nodes"`
21			Edges []edge   `json:"edges"`
22		}{Nodes: nodes}
23		for _, e := range edges {
24			doc.Edges = append(doc.Edges, edge{From: e[0], To: e[1]})
25		}
26		data, err := json.Marshal(doc)
27		if err != nil {
28			t.Fatalf("marshal document: %v", err)
29		}
30		return string(data)
31	}
32	
33	func depPairs(deps []Dependency) [][2]string {
34		pairs := make([][2]string, len(deps))
35		for i, d := range deps {
36			pairs[i] = [2]string{d.From, d.To}
37		}
38		return pairs
39	}
40	
41	// Identical documents report no change as a success with two non-nil empty
42	// lists, and datasets outside the target's derivation (an independent node and
43	// the target's downstream) never enter either list.
44	func TestCompareUpstreamLineageNoChange(t *testing.T) {
45		before := compareDoc(t,
46			[]string{"s", "m", "t", "d", "lone"},
47			[][2]string{{"s", "m"}, {"m", "t"}, {"t", "d"}})
48		after := before
49	
50		diff, err := CompareUpstreamLineage(before, after, "t")
51		if err != nil {
52			t.Fatalf("CompareUpstreamLineage: %v", err)
53		}
54		if diff.Added == nil || diff.Removed == nil {
55			t.Fatalf("no-change result must hold non-nil empty lists, got %+v", diff)
56		}
57		if len(diff.Added) != 0 || len(diff.Removed) != 0 {
58			t.Fatalf("expected no change, got added=%v removed=%v", diff.Added, diff.Removed)
59		}
60	}
61	
62	// A target with no upstreams in both documents compares cleanly even while
63	// unrelated lineage elsewhere changes between the two documents.
64	func TestCompareUpstreamLineageIgnoresUnrelatedChanges(t *testing.T) {
65		before := compareDoc(t, []string{"t", "x", "y"}, [][2]string{{"x", "y"}})
66		// t stays a root: the changed x/y/z chain is independent, and t gains a
67		// downstream, which must never enter its upstream comparison.
68		after := compareDoc(t,
69			[]string{"t", "x", "y", "z", "down"},
70			[][2]string{{"x", "y"}, {"y", "z"}, {"t", "down"}})
71	
72		diff, err := CompareUpstreamLineage(before, after, "t")
73		if err != nil {
74			t.Fatalf("CompareUpstreamLineage: %v", err)
75		}
76		if len(diff.Added) != 0 || len(diff.Removed) != 0 {
77			t.Fatalf("root target should see no change, got added=%v removed=%v",
78				depPairs(diff.Added), depPairs(diff.Removed))
79		}
80	}
81	
82	// Direct dependencies added and removed at the target are reported with the
83	// exports' from-upstream/to-derived direction.
84	func TestCompareUpstreamLineageDirectAddAndRemove(t *testing.T) {
85		before := compareDoc(t,
86			[]string{"keep", "gone", "soon", "t"},
87			[][2]string{{"keep", "t"}, {"gone", "t"}})
88		after := compareDoc(t,
89			[]string{"keep", "gone", "soon", "t"},
90			[][2]string{{"keep", "t"}, {"soon", "t"}})
91	
92		diff, err := CompareUpstreamLineage(before, after, "t")
93		if err != nil {
94			t.Fatalf("CompareUpstreamLineage: %v", err)
95		}
96		if got, want := depPairs(diff.Added), [][2]string{{"soon", "t"}}; !reflect.DeepEqual(got, want) {
97			t.Errorf("Added = %v, want %v", got, want)
98		}
99		if got, want := depPairs(diff.Removed), [][2]string{{"gone", "t"}}; !reflect.DeepEqual(got, want) {
100			t.Errorf("Removed = %v, want %v", got, want)
101		}
102	}
103	
104	// The target reaches s both directly and through m. Removing only the longer
105	// route's edge m -> t must still show, and because that deletion detaches the
106	// whole m segment from the target's derivation, s -> m — which belonged to the
107	// before scope — is removed as well. Nothing is added.
108	func TestCompareUpstreamLineageLongRouteEdgeDeletion(t *testing.T) {
109		before := compareDoc(t,
110			[]string{"s", "m", "t"},
111			[][2]string{{"s", "t"}, {"s", "m"}, {"m", "t"}})
112		after := compareDoc(t,
113			[]string{"s", "m", "t"},
114			[][2]string{{"s", "t"}, {"s", "m"}})
115	
116		diff, err := CompareUpstreamLineage(before, after, "t")
117		if err != nil {
118			t.Fatalf("CompareUpstreamLineage: %v", err)
119		}
120		if len(diff.Added) != 0 {
121			t.Errorf("Added = %v, want none", depPairs(diff.Added))
122		}
123		wantRemoved := [][2]string{{"m", "t"}, {"s", "m"}}
124		if got := depPairs(diff.Removed); !reflect.DeepEqual(got, wantRemoved) {
125			t.Errorf("Removed = %v, want %v", got, wantRemoved)
126		}
127	}
128	
129	// Deleting only the direct s -> t edge keeps the longer route intact, so just
130	// the direct relationship is removed and the route's edges stay common.
131	func TestCompareUpstreamLineageDirectEdgeDeletionKeepsRoute(t *testing.T) {
132		before := compareDoc(t,
133			[]string{"s", "m", "t"},
134			[][2]string{{"s", "t"}, {"s", "m"}, {"m", "t"}})
135		after := compareDoc(t,
136			[]string{"s", "m", "t"},
137			[][2]string{{"s", "m"}, {"m", "t"}})
138	
139		diff, err := CompareUpstreamLineage(before, after, "t")
140		if err != nil {
141			t.Fatalf("CompareUpstreamLineage: %v", err)
142		}
143		if got, want := depPairs(diff.Removed), [][2]string{{"s", "t"}}; !reflect.DeepEqual(got, want) {
144			t.Errorf("Removed = %v, want %v", got, want)
145		}
146		if len(diff.Added) != 0 {
147			t.Errorf("Added = %v, want none", depPairs(diff.Added))
148		}
149	}
150	
151	// The target's direct upstreams do not change — it still derives from m — but
152	// m's own source swaps from old to new. The actual changed dependencies show,
153	// proving the comparison is over the full upstream scope rather than the
154	// target's direct upstream list.
155	func TestCompareUpstreamLineageAncestorSourceSwap(t *testing.T) {
156		before := compareDoc(t,
157			[]string{"old", "new", "m", "t"},
158			[][2]string{{"m", "t"}, {"old", "m"}})
159		after := compareDoc(t,
160			[]string{"old", "new", "m", "t"},
161			[][2]string{{"m", "t"}, {"new", "m"}})
162	
163		diff, err := CompareUpstreamLineage(before, after, "t")
164		if err != nil {
165			t.Fatalf("CompareUpstreamLineage: %v", err)
166		}
167		if got, want := depPairs(diff.Added), [][2]string{{"new", "m"}}; !reflect.DeepEqual(got, want) {
168			t.Errorf("Added = %v, want %v", got, want)
169		}
170		if got, want := depPairs(diff.Removed), [][2]string{{"old", "m"}}; !reflect.DeepEqual(got, want) {
171			t.Errorf("Removed = %v, want %v", got, want)
172		}
173	}
174	
175	// A new multi-hop branch appearing is reported edge by edge, and results are
176	// ordered by From then To in Go string order regardless of document order.
177	func TestCompareUpstreamLineageNewBranchOrdering(t *testing.T) {
178		// Before: a -> t only. After adds b -> mid -> t. Nodes and edges are listed
179		// shuffled and partly repeated in the after document.
180		before := compareDoc(t,
181			[]string{"a", "b", "mid", "t"},
182			[][2]string{{"a", "t"}})
183		after := `{"edges":[{"from":"mid","to":"t"},{"from":"b","to":"mid"},{"from":"a","to":"t"},{"from":"b","to":"mid"}],` +
184			`"nodes":["t","a","mid","b","a"]}`
185	
186		diff, err := CompareUpstreamLineage(before, after, "t")
187		if err != nil {
188			t.Fatalf("CompareUpstreamLineage: %v", err)
189		}
190		wantAdded := [][2]string{{"b", "mid"}, {"mid", "t"}}
191		if got := depPairs(diff.Added); !reflect.DeepEqual(got, wantAdded) {
192			t.Errorf("Added = %v, want %v", got, wantAdded)
193		}
194		if len(diff.Removed) != 0 {
195			t.Errorf("Removed = %v, want none", depPairs(diff.Removed))
196		}
197	}
198	
199	// Both lists sort by From first and then To; duplicate edges in the documents
200	// never duplicate an entry.
201	func TestCompareUpstreamLineageSortsByFromThenTo(t *testing.T) {
202		before := compareDoc(t,
203			[]string{"z", "a", "m", "t"},
204			[][2]string{{"z", "t"}, {"z", "m"}, {"m", "t"}})
205		after := compareDoc(t,
206			[]string{"z", "a", "m", "t"},
207			[][2]string{
208				{"z", "t"}, {"z", "m"}, {"m", "t"}, // survivors
209				{"a", "t"}, {"a", "m"}, // added, both From a: order on To
210			})
211	
212		diff, err := CompareUpstreamLineage(before, after, "t")
213		if err != nil {
214			t.Fatalf("CompareUpstreamLineage: %v", err)
215		}
216		wantAdded := [][2]string{{"a", "m"}, {"a", "t"}}
217		if got := depPairs(diff.Added); !reflect.DeepEqual(got, wantAdded) {
218			t.Errorf("Added = %v, want %v", got, wantAdded)
219		}
220	}
221	
222	// Names compare by their exact decoded value: case and surrounding spaces
223	// matter, so a relationship renamed only by case or whitespace is a real
224	// remove/add pair.
225	func TestCompareUpstreamLineageExactNameMatching(t *testing.T) {
226		before := compareDoc(t, []string{" mid ", "t"}, [][2]string{{" mid ", "t"}})
227		after := compareDoc(t, []string{" mid ", "Mid", "t"}, [][2]string{{"Mid", "t"}})
228	
229		diff, err := CompareUpstreamLineage(before, after, "t")
230		if err != nil {
231			t.Fatalf("CompareUpstreamLineage: %v", err)
232		}
233		if got, want := depPairs(diff.Added), [][2]string{{"Mid", "t"}}; !reflect.DeepEqual(got, want) {
234			t.Errorf("Added = %v, want %v", got, want)
235		}
236		if got, want := depPairs(diff.Removed), [][2]string{{" mid ", "t"}}; !reflect.DeepEqual(got, want) {
237			t.Errorf("Removed = %v, want %v", got, want)
238		}
239	}
240	
241	// An empty target is rejected without either document being inspected first:
242	// even malformed documents yield the missing-target error.
243	func TestCompareUpstreamLineageEmptyTarget(t *testing.T) {
244		_, err := CompareUpstreamLineage("not json", "also not json", "")
245		if err == nil || err.Error() != "target dataset name is required" {
246			t.Fatalf("error = %v, want target dataset name is required", err)
247		}
248	}
249	
250	// A target missing from either valid document fails the whole comparison with
251	// the target named and the offending document identified, and no partial
252	// lists.
253	func TestCompareUpstreamLineageTargetNotRegistered(t *testing.T) {
254		withT := compareDoc(t, []string{"s", "t"}, [][2]string{{"s", "t"}})
255		withoutT := compareDoc(t, []string{"s"}, nil)
256	
257		if _, err := CompareUpstreamLineage(withoutT, withT, "t"); err == nil {
258			t.Fatal("expected error when target missing from before document")
259		} else {
260			msg := err.Error()
261			if !strings.Contains(msg, "t") || !strings.Contains(msg, "before-change") {
262				t.Fatalf("error %q must name the target and the before-change document", msg)
263			}
264		}
265	
266		if _, err := CompareUpstreamLineage(withT, withoutT, "t"); err == nil {
267			t.Fatal("expected error when target missing from after document")
268		} else {
269			msg := err.Error()
270			if !strings.Contains(msg, "t") || !strings.Contains(msg, "after-change") {
271				t.Fatalf("error %q must name the target and the after-change document", msg)
272			}
273		}
274	}
275	
276	// A document that fails import validation is rejected as a whole; the error
277	// states which document (before or after) was rejected and why, and no partial
278	// difference comes back.
279	func TestCompareUpstreamLineageRejectsInvalidDocuments(t *testing.T) {
280		good := compareDoc(t, []string{"s", "t"}, [][2]string{{"s", "t"}})
281	
282		cyclic := compareDoc(t,
283			[]string{"a", "b", "t"},
284			[][2]string{{"a", "b"}, {"b", "a"}})
285		dangling := compareDoc(t,
286			[]string{"t"},
287			[][2]string{{"ghost", "t"}})
288	
289		if _, err := CompareUpstreamLineage(cyclic, good, "t"); err == nil {
290			t.Fatal("expected rejection of cyclic before document")
291		} else if msg := err.Error(); !strings.Contains(msg, "before-change") || !strings.Contains(msg, "cycle") {
292			t.Fatalf("error %q must identify the before-change document and its cycle", msg)
293		}
294	
295		if _, err := CompareUpstreamLineage(good, cyclic, "t"); err == nil {
296			t.Fatal("expected rejection of cyclic after document")
297		} else if msg := err.Error(); !strings.Contains(msg, "after-change") || !strings.Contains(msg, "cycle") {
298			t.Fatalf("error %q must identify the after-change document and its cycle", msg)
299		}
300	
301		if _, err := CompareUpstreamLineage(good, dangling, "t"); err == nil {
302			t.Fatal("expected rejection of after document with a missing edge endpoint")
303		} else if msg := err.Error(); !strings.Contains(msg, "after-change") || !strings.Contains(msg, "ghost") {
304			t.Fatalf("error %q must identify the after-change document and the ghost endpoint", msg)
305		}
306	}
307	
308	// When both documents are invalid, the before document is validated first and
309	// its rejection is the one reported. Document validation also precedes target
310	// presence checks.
311	func TestCompareUpstreamLineageValidatesBeforeFirst(t *testing.T) {
312		cyclic := compareDoc(t, []string{"a"}, [][2]string{{"a", "a"}})
313		// Target also absent from both documents; document rejection must win.
314		if _, err := CompareUpstreamLineage(cyclic, cyclic, "ghost"); err == nil {
315			t.Fatal("expected before-document rejection")
316		} else if msg := err.Error(); !strings.HasPrefix(msg, "before-change") {
317			t.Fatalf("error %q must be the before-document rejection", msg)
318		}
319	}
320	
321	// The comparison only builds throwaway graphs and never mutates or depends on
322	// the caller's own graph: passing documents round-trips through import with no
323	// shared state, and calling twice yields identical results.
324	func TestCompareUpstreamLineageDeterministic(t *testing.T) {
325		before := compareDoc(t,
326			[]string{"o", "n", "m", "t"},
327			[][2]string{{"o", "m"}, {"m", "t"}})
328		after := compareDoc(t,
329			[]string{"o", "n", "m", "t"},
330			[][2]string{{"n", "m"}, {"m", "t"}})
331	
332		first, err := CompareUpstreamLineage(before, after, "t")
333		if err != nil {
334			t.Fatalf("first comparison: %v", err)
335		}
336		second, err := CompareUpstreamLineage(before, after, "t")
337		if err != nil {
338			t.Fatalf("second comparison: %v", err)
339		}
340		if !reflect.DeepEqual(first, second) {
341			t.Fatalf("comparisons differ:\n%+v\n%+v", first, second)
342		}
343		if got, want := depPairs(first.Added), [][2]string{{"n", "m"}}; !reflect.DeepEqual(got, want) {
344			t.Errorf("Added = %v, want %v", got, want)
345		}
346		if got, want := depPairs(first.Removed), [][2]string{{"o", "m"}}; !reflect.DeepEqual(got, want) {
347			t.Errorf("Removed = %v, want %v", got, want)
348		}
349	}
