9	// These tests guard name identity when a lineage document spells code points
10	// with \u escapes. encoding/json accepts a lone surrogate escape and rewrites
11	// it to U+FFFD, which used to collapse two different names into one "�" and
12	// let a bad edge endpoint attach to a real dataset named "�". Every unpaired
13	// surrogate escape must now fail the whole import; matched pairs, the real
14	// replacement character and escaped backslashes stay ordinary, exact names.
15	
16	// surrogateImportFails runs one import that must be rejected wholesale: nil
17	// graph, an error that states the unpaired-surrogate rule, the location
18	// (node name / edge "from" / edge "to") and the escape in its original
19	// \uXXXX spelling rather than a shared replacement glyph.
20	func surrogateImportFails(t *testing.T, text, location, escape string) {
21		t.Helper()
22		graph, err := ImportLineage(text)
23		if err == nil {
24			t.Fatalf("ImportLineage(%s) succeeded with %v, want unpaired-surrogate error", text, graph)
25		}
26		if graph != nil {
27			t.Fatalf("failed import returned a partial graph %v, want nil", graph)
28		}
29		msg := err.Error()
30		for _, want := range []string{"unpaired Unicode surrogate escape", location, escape} {
31			if !strings.Contains(msg, want) {
32				t.Errorf("error %q must contain %q", msg, want)
33			}
34		}
35		if strings.ContainsRune(msg, '�') {
36			t.Errorf("error %q must not render the bad escape as a replacement character", msg)
37		}
38	}
