40	// The exact failure from the bug report: two distinct lone-high escapes are
41	// different names and must not both decode to one "�".
42	func TestImportLineageRejectsTwoDifferentLoneHighNodeNames(t *testing.T) {
43		text := `{"nodes":["\ud800","\ud801"],"edges":[]}`
44		surrogateImportFails(t, text, "node name", `\ud800`)
