47		// escape that appeared instead of converging on the same glyph.
48		for _, doc := range []string{
49			`{"nodes":["\ud800"],"edges":[]}`,
50			`{"nodes":["\ud801"],"edges":[]}`,
51		} {
52			_, err := ImportLineage(doc)
53			if err == nil {
54				t.Fatalf("ImportLineage(%s) succeeded, want error", doc)
55			}
56			if !strings.Contains(err.Error(), doc[strings.Index(doc, `\u`):strings.Index(doc, `\u`)+6]) {
57				t.Errorf("error %q must preserve the raw escape from %s", err.Error(), doc)
58			}
59		}
60		_, err1 := ImportLineage(`{"nodes":["\ud800"],"edges":[]}`)
61		_, err2 := ImportLineage(`{"nodes":["\ud801"],"edges":[]}`)
62		if err1.Error() == err2.Error() {
63			t.Errorf("distinct bad names produced the same error %q", err1.Error())
