67	// Every shape of unpaired surrogate in a node name is rejected, even with
68	// valid nodes sitting beside it (no partial graph comes back).
69	func TestImportLineageRejectsUnpairedNodeSurrogates(t *testing.T) {
70		cases := []struct {
71			name   string
