79			{"lone low after text", `"ab\ude00"`, `\ude00`},
80			{"uppercase hex lone high", `"\uD800"`, `\uD800`},
81			{"reversed low then high", `"\udc00\ud83d"`, `\udc00`},
82			{"high high low", `"\ud83d\ud83d\ude00"`, `\ud83d`},
83			{"high then letters then low", `"\ud83d x\ude00"`, `\ud83d`},
84			{"high then other escape then low", `"\ud83d\n\ude00"`, `\ud83d`},
85			{"high then valid non-surrogate escape", `"\ud83d\u0041"`, `\ud83d`},
86			{"valid pair followed by lone high", `"\ud83d\ude00\ud800"`, `\ud800`},
87			{"valid pair followed by lone low", `"a\ud83d\ude00b\udc00c"`, `\udc00`},
88			{"lone high at end of string", `"\ud83d\ude00x\udbff"`, `\udbff`},
89			{"bad escape in middle of name", `"pre\ud800post"`, `\ud800`},
90		}
91		for _, tc := range cases {
92			t.Run(tc.name, func(t *testing.T) {
93				// A valid node alongside the bad one must not rescue the import.
94				text := `{"nodes":["perfectly-fine",` + tc.token + `],"edges":[]}`
95				surrogateImportFails(t, text, "node name", tc.escape)
96			})
97		}
98	}
