100	// Unpaired surrogates in edge endpoints are rejected too, and the error says
101	// whether they came from "from" or "to".
102	func TestImportLineageRejectsUnpairedEdgeEndpointSurrogates(t *testing.T) {
103		t.Run("bad from", func(t *testing.T) {
