198	// An escaped backslash followed by letters is ordinary text: the document
199	// token "\\ud800" is the six-character name \ud800 (backslash, u, d, 8, 0, 0),
200	// not a surrogate escape, and it survives import, queries and export intact.
201	func TestImportLineageEscapedBackslashBeforeUdIsLiteralName(t *testing.T) {
202		const literal = `\ud800` // decoded value of the JSON token "\\ud800"
203		text := `{"nodes":["\\ud800","a"],` +
204			`"edges":[{"from":"\\ud800","to":"a"}]}`
205		graph := mustImport(t, text)
206		assertConsistent(t, graph)
207		if graph[literal] == nil {
208			t.Fatalf("graph must hold literal name %q, got %v", literal, graph)
209		}
210		assertEntry(t, graph, literal, nil, []string{"a"})
211		assertEntry(t, graph, "a", []string{literal}, nil)
212	
213		// It is a normal name for queries, and exports with a doubled backslash so
214		// a reader recovers exactly \ud800 rather than a surrogate escape.
215		if hits := mustImpacts(t, graph, literal); len(hits) != 1 || hits[0].Dataset != "a" {
216			t.Errorf("Impacts(%q) = %v, want [a]", literal, hits)
217		}
218		out := mustExport(t, graph, "a")
219		if !strings.Contains(out, `"\\ud800"`) {
220			t.Errorf("export %s must write the literal name as %q", out, `\\ud800`)
221		}
222		reimported := mustImport(t, out)
223		if reimported[literal] == nil {
224			t.Fatalf("re-import lost the literal backslash name, got %v", reimported)
225		}
226		if again := mustExport(t, reimported, "a"); again != out {
227			t.Errorf("re-export differs:\n%s\n%s", out, again)
228		}
229	}
