231	// Surrogate validation never disturbs ordinary \u escapes: non-surrogate code
232	// points spelled with \u keep their decoded value, including \u0000 (which is
233	// a legal non-empty name) and escapes standing next to paired surrogates.
234	func TestImportLineageOrdinaryUEscapesStillDecode(t *testing.T) {
235		text := `{"nodes":["\u4e2d\u6587","x\u0041","\u0000","\ud83d\ude00"],` +
236			`"edges":[{"from":"\u4e2d\u6587","to":"x\u0041"},` +
237			`{"from":"\ud83d\ude00","to":"x\u0041"}]}`
238		graph := mustImport(t, text)
239		for _, name := range []string{"中文", "xA", "😀"} {
240			if graph[name] == nil {
241				t.Errorf("missing decoded name %q in %v", name, graph)
242			}
243		}
244		if graph["\u0000"] == nil {
245			t.Error("U+0000 is a legal non-empty name")
246		}
247		assertEntry(t, graph, "中文", nil, []string{"xA"})
248		assertEntry(t, graph, "xA", []string{"中文", "😀"}, nil)
249	}
